#!/usr/bin/env bash
set -euo pipefail

PORTAL_DIR="${1:-target/report-portal}"
PDF_DIR="${2:-$PORTAL_DIR/reports}"
mkdir -p "$PDF_DIR" "$PORTAL_DIR/pdf-source"

chrome_bin="${CHROME_BIN:-google-chrome}"
if ! command -v "$chrome_bin" >/dev/null 2>&1; then
  if command -v chrome >/dev/null 2>&1; then chrome_bin="chrome"; fi
fi

cat > "$PORTAL_DIR/pdf-source/allure-print.html" <<'HTML'
<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Allure Test Report 6-3-2026</title><style>body{font-family:Arial,sans-serif;margin:28px;color:#172033}h1{background:#0f172a;color:white;padding:16px}h2{border-bottom:1px solid #d9e1ee;padding-bottom:6px}table{width:100%;border-collapse:collapse;margin:12px 0 24px}th,td{border:1px solid #d9e1ee;padding:8px;text-align:left;vertical-align:top}th{background:#eef3f9}.ok{color:#087f5b;font-weight:bold}.warn{color:#a16207;font-weight:bold}.bad{color:#b91c1c;font-weight:bold}.page{page-break-after:always}</style></head><body><h1>Allure Test Report - 6/3/2026</h1><p><b>Repository:</b> https://github.com/BrianGator/DTCC-Selenium-Cucumber-Automation/</p><p><b>Website Under Test:</b> https://www.dtcc.com/</p><p><b>Owner:</b> Brian McCarthy</p><h2>Overview</h2><table><tr><th>Metric</th><th>Value</th><th>Meaning</th></tr><tr><td>Total detailed tests</td><td>82+</td><td>Allure suite combines UI, API, database, reporting UI, quality gates, and optional failure demos.</td></tr><tr><td>Stable pass gate</td><td class="ok">At least 85%</td><td>Quality gate test verifies stable release-readiness threshold.</td></tr><tr><td>Intentional failures</td><td class="warn">Opt-in only</td><td>Enable only with includeIntentionalFailures=true to populate failure examples.</td></tr></table><h2>Allure Tab Data Summary</h2><table><tr><th>Allure Tab</th><th>Fields to Review</th><th>Expected Data</th></tr><tr><td>Overview</td><td>Launch summary, trend, categories, suites, environment, executor.</td><td>Run metadata, repository, website, profile, Chrome headless, Java 17, Maven.</td></tr><tr><td>Categories</td><td>Defect categories and failure groupings.</td><td>Intentional demo failures, security validation failures, API contract failures, browser UI failures, skipped demos.</td></tr><tr><td>Suites</td><td>Test classes and individual test methods.</td><td>AllureEnabledUiReportTest, DtccPublicAllureShowcaseTest, DtccExtendedAllureCoverageTest, DtccAdditionalAllureCoverageTest, UI/API/DB tests.</td></tr><tr><td>Graphs</td><td>Trend, status, duration, severity, categories.</td><td>History is restored from gh-pages and seeded when no prior history exists.</td></tr><tr><td>Timeline</td><td>Test execution timing.</td><td>UI, API, DB, and report UI tests grouped by execution time.</td></tr><tr><td>Behaviors</td><td>Epic, feature, story hierarchy.</td><td>DTCC public website, backend API, database validation, quality gates, intentional failures.</td></tr><tr><td>Packages</td><td>Java package view.</td><td>com.dtcc.automation.reports, api, database, ui, selenide, publicsite.</td></tr></table><div class="page"></div><h2>Quality Gates</h2><table><tr><th>Gate</th><th>Target</th><th>Status</th></tr><tr><td>Stable pass rate</td><td>Greater than or equal to 85%</td><td class="ok">Expected pass</td></tr><tr><td>Blocker defects</td><td>0</td><td class="ok">Expected pass</td></tr><tr><td>Global metadata</td><td>Present</td><td class="ok">Environment, executor, repository, website, owner.</td></tr><tr><td>Intentional UI/API/DB defects</td><td>Opt-in</td><td class="warn">Skipped unless enabled.</td></tr></table><h2>DTCC Website Areas</h2><table><tr><th>Area</th><th>Report Evidence</th></tr><tr><td>Home</td><td>Branding, public URL, page body, navigation.</td></tr><tr><td>Client Center</td><td>Documentation, support links, downloads, contacts, onboarding.</td></tr><tr><td>Important Notices</td><td>Notice search, filters, date sorting, PDF links.</td></tr><tr><td>Products and Services</td><td>Product/service taxonomy and internal links.</td></tr><tr><td>Legal and Regulatory</td><td>Compliance pages, terms, public regulatory references.</td></tr><tr><td>Global Trade Repository</td><td>Dynamic tables, filtering, sorting, pagination, synchronization.</td></tr><tr><td>PDF Library</td><td>Download status, content type, naming, text validation plan.</td></tr></table></body></html>
HTML

cat > "$PORTAL_DIR/pdf-source/cucumber-print.html" <<'HTML'
<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Cucumber Test Report 6-3-2026</title><style>body{font-family:Arial,sans-serif;margin:28px;color:#172033}h1{background:#0f172a;color:white;padding:16px}table{width:100%;border-collapse:collapse;margin:12px 0 24px}th,td{border:1px solid #d9e1ee;padding:8px;text-align:left;vertical-align:top}th{background:#eef3f9}</style></head><body><h1>Cucumber Test Report - 6/3/2026</h1><p><b>Purpose:</b> Business-readable BDD evidence for DTCC public website, backend/API, and database/reporting checks.</p><table><tr><th>Feature Group</th><th>Scenario Coverage</th><th>Expected Report Fields</th></tr><tr><td>DTCC website areas</td><td>About, Client Center, Important Notices, Products and Services, Legal and Regulatory, News, Careers, Global Trade Repository, PDF Library, Search.</td><td>Feature, scenario, examples table, Given/When/Then steps, pass/fail status.</td></tr><tr><td>Backend/API behavior</td><td>Market status, notice search, document metadata, service directory, invalid query, missing auth, rate limit, contract version.</td><td>Scenario outline example rows, status code, key field, expected result.</td></tr><tr><td>Database/reporting evidence</td><td>Settlement order, audit trail, document access, reference data, PII masking, stale records, reconciliation.</td><td>Validation name, table/view, expected result.</td></tr></table><p>Open the live Cucumber HTML report in the portal for exact generated scenarios and step execution details.</p></body></html>
HTML

cat > "$PORTAL_DIR/pdf-source/surefire-print.html" <<'HTML'
<!doctype html><html lang="en"><head><meta charset="utf-8"><title>TestNG Surefire Report 6-3-2026</title><style>body{font-family:Arial,sans-serif;margin:28px;color:#172033}h1{background:#0f172a;color:white;padding:16px}table{width:100%;border-collapse:collapse;margin:12px 0 24px}th,td{border:1px solid #d9e1ee;padding:8px;text-align:left;vertical-align:top}th{background:#eef3f9}.ok{color:#087f5b;font-weight:bold}.warn{color:#a16207;font-weight:bold}</style></head><body><h1>TestNG Surefire Test Report - 6/3/2026</h1><p><b>Purpose:</b> Raw Maven/TestNG execution evidence for CI diagnostics.</p><table><tr><th>Field</th><th>Meaning</th></tr><tr><td>testng-results.xml</td><td>Machine-readable status for suites, classes, methods, failures, errors, and skipped tests.</td></tr><tr><td>emailable-report.html</td><td>TestNG summary report when generated.</td></tr><tr><td>surefire text files</td><td>Runner-level output and stack traces.</td></tr><tr><td>Skipped intentional demos</td><td class="warn">Expected when includeIntentionalFailures=false.</td></tr><tr><td>Stable failures/errors</td><td class="ok">Should be zero in the default allure-ui run.</td></tr></table></body></html>
HTML

cat > "$PORTAL_DIR/pdf-source/dashboard-print.html" <<'HTML'
<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Website Dashboard Consolidated Report 6-3-2026</title><style>body{font-family:Arial,sans-serif;margin:28px;color:#172033}h1{background:#0f172a;color:white;padding:16px}table{width:100%;border-collapse:collapse;margin:12px 0 24px}th,td{border:1px solid #d9e1ee;padding:8px;text-align:left;vertical-align:top}th{background:#eef3f9}.ok{color:#087f5b;font-weight:bold}.warn{color:#a16207;font-weight:bold}</style></head><body><h1>Website Dashboard Consolidated Report - 6/3/2026</h1><p><b>Repository:</b> https://github.com/BrianGator/DTCC-Selenium-Cucumber-Automation/</p><p><b>Website:</b> https://www.dtcc.com/</p><p><b>Owner:</b> Brian McCarthy</p><table><tr><th>Dashboard Section</th><th>Displayed Data</th></tr><tr><td>Quality gates</td><td>Total detailed tests, UI/API/DB coverage, stable pass gate, opt-in failures.</td></tr><tr><td>DTCC website area status</td><td>Home, Client Center, Important Notices, Products and Services, Legal and Regulatory, Global Trade Repository, PDF Library.</td></tr><tr><td>Allure analytics data pack</td><td>Test base growth, stability by epics/features/stories, duration histogram, status age, testing pyramid, transitions, dynamics.</td></tr><tr><td>Supporting logs explanation</td><td>What Allure, Cucumber, Surefire/TestNG, and static dashboards are used for.</td></tr><tr><td>Embedded Allure report</td><td>The main portal embeds the live Allure report for a single-page review experience.</td></tr></table></body></html>
HTML

print_pdf() {
  local input="$1"
  local output="$2"
  "$chrome_bin" --headless=new --no-sandbox --disable-gpu --disable-dev-shm-usage --run-all-compositor-stages-before-draw --virtual-time-budget=10000 --print-to-pdf="$output" "file://$(cd "$(dirname "$input")" && pwd)/$(basename "$input")" >/dev/null 2>&1 || true
}

print_pdf "$PORTAL_DIR/pdf-source/allure-print.html" "$PDF_DIR/Allure-Test-Report-6-3-2026.pdf"
print_pdf "$PORTAL_DIR/pdf-source/cucumber-print.html" "$PDF_DIR/Cucumber-Test-Report-6-3-2026.pdf"
print_pdf "$PORTAL_DIR/pdf-source/surefire-print.html" "$PDF_DIR/Test-NG-Sunfire-Test-Report-6-3-2026.pdf"
print_pdf "$PORTAL_DIR/pdf-source/dashboard-print.html" "$PDF_DIR/Website-Dashboard-Consolidated-Report-6-3-2026.pdf"

cat > "$PDF_DIR/index.html" <<HTML
<!doctype html><html lang="en"><head><meta charset="utf-8"><title>PDF Reports</title><style>body{font-family:Arial,sans-serif;margin:32px}li{margin:10px 0}</style></head><body><h1>PDF Reports - 6/3/2026</h1><ul><li><a href="Allure-Test-Report-6-3-2026.pdf">Allure-Test-Report-6-3-2026.pdf</a></li><li><a href="Cucumber-Test-Report-6-3-2026.pdf">Cucumber-Test-Report-6-3-2026.pdf</a></li><li><a href="Test-NG-Sunfire-Test-Report-6-3-2026.pdf">Test-NG-Sunfire-Test-Report-6-3-2026.pdf</a></li><li><a href="Website-Dashboard-Consolidated-Report-6-3-2026.pdf">Website-Dashboard-Consolidated-Report-6-3-2026.pdf</a></li></ul></body></html>
HTML

ls -lh "$PDF_DIR"
